CREATE OR REPLACE FUNCTION public.tms_access_selftest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claims text; person record; result jsonb:='[]'; snapshot jsonb; BEGIN IF NOT public.tms_module('/usuarios') THEN RAISE EXCEPTION 'Apenas administradores ativos'; END IF; claims:=current_setting('request.jwt.claims',true); FOR person IN SELECT p.id,ur.role FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id WHERE p.ativo LOOP PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',person.id,'role','authenticated')::text,true); IF person.role<>'admin' AND public.tms_module('/usuarios') THEN RAISE EXCEPTION 'Admin scope leaked'; END IF; IF person.role='operacao' AND NOT public.tms_module('/coletas') THEN RAISE EXCEPTION 'Operations scope denied'; END IF; IF person.role='comercial' AND NOT public.tms_module('/clientes') THEN RAISE EXCEPTION 'Commercial scope denied'; END IF; IF person.role='financeiro' AND NOT public.tms_module('/financeiro') THEN RAISE EXCEPTION 'Finance scope denied'; END IF; snapshot:=public.tms_records_read(); IF NOT public.tms_module('/financeiro') AND EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot) x WHERE x->>'collection'='orders' AND (x->'data' ? 'xmlOriginal' OR x->'data' ? 'cteValor' OR coalesce((x->'data'->>'valorFrete')::numeric,0)<>0)) THEN RAISE EXCEPTION 'Financial fields leaked'; END IF; BEGIN UPDATE public.profiles SET ativo=false WHERE id=person.id; IF public.tms_active() OR public.tms_module('/usuarios') OR public.tms_collection('orders','read') THEN RAISE EXCEPTION 'Inactive user authorized'; END IF; BEGIN PERFORM public.tms_records_read(); RAISE EXCEPTION USING ERRCODE='P0003',MESSAGE='Inactive read allowed'; EXCEPTION WHEN raise_exception THEN NULL; END; RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='rollback'; EXCEPTION WHEN no_data_found THEN NULL; END; result:=result||jsonb_build_array(jsonb_build_object('role',person.role,'moduleChecks','passed','inactive','blocked','redaction','passed')); END LOOP; PERFORM set_config('request.jwt.claims',claims,true); RETURN jsonb_build_object('status','passed','checks',result,'data_persisted',false); END $$;
REVOKE ALL ON FUNCTION public.tms_access_selftest() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.tms_access_selftest() TO authenticated,service_role;